from collections import deque

class Solution:
    def minStepToReachTarget(self, knightPos: list, targetPos: list, N: int) -> int:
        if knightPos == targetPos:
            return 0

        moves = [
            (2, 1), (1, 2), (-1, 2), (-2, 1),
            (-2, -1), (-1, -2), (1, -2), (2, -1)
        ]

        visited = [[False] * (N + 1) for _ in range(N + 1)]
        queue = deque()
        start_x, start_y = knightPos[0], knightPos[1]
        queue.append((start_x, start_y, 0))
        visited[start_x][start_y] = True

        while queue:
            x, y, dist = queue.popleft()

            if x == targetPos[0] and y == targetPos[1]:
                return dist

            for dx, dy in moves:
                nx, ny = x + dx, y + dy
                if 1 <= nx <= N and 1 <= ny <= N and not visited[nx][ny]:
                    visited[nx][ny] = True
                    queue.append((nx, ny, dist + 1))

        return -1
